  "implementation": "def solve(case):
    import json

    nodes = case['nodes']
    core_distance = case['core_distance']
    distances_raw = case['distances']

    # Build distance lookup (sorted tuple -> weight)
    dist_map = {}
    for a, b, d in distances_raw:
        key = tuple(sorted((a, b)))
        dist_map[key] = d

    # Build all mutual reachability edges
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i + 1, n):
            u = nodes[i]
            v = nodes[j]
            pair = (u, v)
            pairwise_d = dist_map.get(pair)
            if pairwise_d is None:
                raise ValueError(f"Missing distance for {pair}")
            mutual = max(core_distance[u], core_distance[v], pairwise_d)
            # Canonicalize edge: ensure first node lexicographically smaller
            first, second = (u, v) if u < v else (v, u)
            edges.append((mutual, first, second))

    # Sort deterministically: by weight, then first node, then second node
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; cannot build MST")

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
